var e={"pr-1th-5-18":{e:`web`,t:[`In everything give thanks, for this is the will of God in Christ Jesus toward you.`]},"pr-ps-100-4":{e:`web`,t:[`Enter into his gates with thanksgiving, and into his courts with praise. Give thanks to him, and bless his name.`]},"pr-col-3-15":{e:`web`,t:[`And let the peace of God rule in your hearts, to which also you were called in one body, and be thankful.`]},"pr-phil-4-6":{e:`web`,t:[`In nothing be anxious, but in everything, by prayer and petition with thanksgiving, let your requests be made known to God.`]},"pr-ps-107-1":{e:`web`,t:[`Give thanks to Yahweh, for he is good, for his loving kindness endures forever.`]},"pr-jas-1-17":{e:`web`,t:[`Every good gift and every perfect gift is from above, coming down from the Father of lights, with whom can be no variation, nor turning shadow.`]},"pr-mic-6-8":{e:`web`,t:[`He has shown you, O man, what is good. What does Yahweh require of you, but to act justly, to love mercy, and to walk humbly with your God?`]},"pr-phil-2-3":{e:`web`,t:[`doing nothing through rivalry or through conceit, but in humility, each counting others better than himself;`]},"pr-prov-11-2":{e:`web`,t:[`When pride comes, then comes shame, but with humility comes wisdom.`]},"pr-jas-4-10":{e:`web`,t:[`Humble yourselves in the sight of the Lord, and he will exalt you.`]},"pr-eph-4-2":{e:`web`,t:[`with all lowliness and humility, with patience, bearing with one another in love,`]},"pr-luke-14-11":{e:`web`,t:[`For everyone who exalts himself will be humbled, and whoever humbles himself will be exalted.”`]},"pr-josh-1-9":{e:`web`,t:[`Haven’t I commanded you? Be strong and courageous. Don’t be afraid. Don’t be dismayed, for Yahweh your God is with you wherever you go.”`]},"pr-2tim-1-7":{e:`web`,t:[`For God didn’t give us a spirit of fear, but of power, love, and self-control.`]},"pr-ps-27-14":{e:`web`,t:[`Wait for Yahweh. Be strong, and let your heart take courage. Yes, wait for Yahweh.`]},"pr-isa-41-10":{e:`web`,t:[`Don’t you be afraid, for I am with you. Don’t be dismayed, for I am your God. I will strengthen you. Yes, I will help you. Yes, I will uphold you with the right hand of my righteousness.`]},"pr-john-16-33":{e:`web`,t:[`I have told you these things, that in me you may have peace. In the world you have trouble; but cheer up! I have overcome the world.”`]},"pr-ps-112-7":{e:`web`,t:[`He will not be afraid of evil news. His heart is steadfast, trusting in Yahweh.`]},"pr-eph-4-32":{e:`web`,t:[`And be kind to one another, tender hearted, forgiving each other, just as God also in Christ forgave you.`]},"pr-col-3-13":{e:`web`,t:[`bearing with one another, and forgiving each other, if any man has a complaint against any; even as Christ forgave you, so you also do.`]},"pr-matt-18-21-22":{e:`web`,t:[`Then Peter came and said to him, “Lord, how often shall my brother sin against me, and I forgive him? Until seven times?”`,`Jesus said to him, “I don’t tell you until seven times, but, until seventy times seven.`]},"pr-prov-17-9":{e:`web`,t:[`He who covers an offense promotes love; but he who repeats a matter separates best friends.`]},"pr-luke-6-37":{e:`web`,t:[`Don’t judge, and you won’t be judged. Don’t condemn, and you won’t be condemned. Set free, and you will be set free.`]},"pr-prov-10-12":{e:`web`,t:[`Hatred stirs up strife, but love covers all wrongs.`]},"pr-jas-1-5":{e:`web`,t:[`But if any of you lacks wisdom, let him ask of God, who gives to all liberally and without reproach, and it will be given to him.`]},"pr-prov-19-20":{e:`web`,t:[`Listen to counsel and receive instruction, that you may be wise in your latter end.`]},"pr-prov-12-15":{e:`web`,t:[`The way of a fool is right in his own eyes, but he who is wise listens to counsel.`]},"pr-ps-90-12":{e:`web`,t:[`So teach us to count our days, that we may gain a heart of wisdom.`]},"pr-jas-3-17":{e:`web`,t:[`But the wisdom that is from above is first pure, then peaceful, gentle, reasonable, full of mercy and good fruits, without partiality, and without hypocrisy.`]},"pr-prov-16-16":{e:`web`,t:[`How much better it is to get wisdom than gold! Yes, to get understanding is to be chosen rather than silver.`]},"pr-acts-20-35":{e:`web`,t:[`In all things I gave you an example, that so laboring you ought to help the weak, and to remember the words of the Lord Jesus, that he himself said, ‘It is more blessed to give than to receive.’”`]},"pr-2cor-9-7":{e:`web`,t:[`Let each man give according as he has determined in his heart, not grudgingly or under compulsion, for God loves a cheerful giver.`]},"pr-prov-11-25":{e:`web`,t:[`The liberal soul shall be made fat. He who waters shall be watered also himself.`]},"pr-matt-6-3-4":{e:`web`,t:[`But when you do merciful deeds, don’t let your left hand know what your right hand does,`,`so that your merciful deeds may be in secret, then your Father who sees in secret will reward you openly.`]},"pr-1jn-3-17-18":{e:`web`,t:[`But whoever has the world’s goods and sees his brother in need, then closes his heart of compassion against him, how does God’s love remain in him?`,`My little children, let’s not love in word only, or with the tongue only, but in deed and truth.`]},"pr-prov-19-17":{e:`web`,t:[`He who has pity on the poor lends to Yahweh; he will reward him.`]},"pr-prov-25-28":{e:`web`,t:[`Like a city that is broken down and without walls is a man whose spirit is without restraint.`]},"pr-prov-16-32":{e:`web`,t:[`One who is slow to anger is better than the mighty; one who rules his spirit, than he who takes a city.`]},"pr-gal-5-22-23":{e:`web`,t:[`But the fruit of the Spirit is love, joy, peace, patience, kindness, goodness, faith,`,`gentleness, and self-control. Against such things there is no law.`]},"pr-jas-1-19":{e:`web`,t:[`So, then, my beloved brothers, let every man be swift to hear, slow to speak, and slow to anger;`]},"pr-prov-29-11":{e:`web`,t:[`A fool vents all of his anger, but a wise man brings himself under control.`]},"pr-titus-2-12":{e:`web`,t:[`instructing us to the intent that, denying ungodliness and worldly lusts, we would live soberly, righteously, and godly in this present age;`]},"pr-col-3-23":{e:`web`,t:[`And whatever you do, work heartily, as for the Lord, and not for men,`]},"pr-gal-6-9":{e:`web`,t:[`Let’s not be weary in doing good, for we will reap in due season, if we don’t give up.`]},"pr-prov-6-6-8":{e:`web`,t:[`Go to the ant, you sluggard. Consider her ways, and be wise;`,`which having no chief, overseer, or ruler,`,`provides her bread in the summer, and gathers her food in the harvest.`]},"pr-prov-21-5":{e:`web`,t:[`The plans of the diligent surely lead to profit; and everyone who is hasty surely rushes to poverty.`]},"pr-1cor-15-58":{e:`web`,t:[`Therefore, my beloved brothers, be steadfast, immovable, always abounding in the Lord’s work, because you know that your labor is not in vain in the Lord.`]},"pr-prov-13-4":{e:`web`,t:[`The soul of the sluggard desires, and has nothing, but the desire of the diligent shall be fully satisfied.`]},"pr-rom-12-12":{e:`web`,t:[`rejoicing in hope; enduring in troubles; continuing steadfastly in prayer;`]},"pr-eccl-7-8":{e:`web`,t:[`Better is the end of a thing than its beginning. The patient in spirit is better than the proud in spirit.`]},"pr-prov-14-29":{e:`web`,t:[`He who is slow to anger has great understanding, but he who has a quick temper displays folly.`]},"pr-1cor-13-4":{e:`web`,t:[`Love is patient and is kind. Love doesn’t envy. Love doesn’t brag, is not proud,`]},"pr-ps-37-7":{e:`web`,t:[`Rest in Yahweh, and wait patiently for him. Don’t fret because of him who prospers in his way, because of the man who makes wicked plots happen.`]},"pr-prov-15-18":{e:`web`,t:[`A wrathful man stirs up contention, but one who is slow to anger appeases strife.`]},"pr-john-14-27":{e:`web`,t:[`Peace I leave with you. My peace I give to you; not as the world gives, I give to you. Don’t let your heart be troubled, neither let it be fearful.`]},"pr-isa-26-3":{e:`web`,t:[`You will keep whoever’s mind is steadfast in perfect peace, because he trusts in you.`]},"pr-matt-5-9":{e:`web`,t:[`Blessed are the peacemakers, for they shall be called children of God.`]},"pr-rom-12-18":{e:`web`,t:[`If it is possible, as much as it is up to you, be at peace with all men.`]},"pr-ps-4-8":{e:`web`,t:[`In peace I will both lay myself down and sleep, for you, Yahweh alone, make me live in safety.`]},"pr-ps-34-14":{e:`web`,t:[`Depart from evil, and do good. Seek peace, and pursue it.`]},"pr-2cor-1-3-4":{e:`web`,t:[`Blessed be the God and Father of our Lord Jesus Christ, the Father of mercies and God of all comfort;`,`who comforts us in all our affliction, that we may be able to comfort those who are in any affliction, through the comfort with which we ourselves are comforted by God.`]},"pr-matt-11-28":{e:`web`,t:[`“Come to me, all you who labor and are heavily burdened, and I will give you rest.`]},"pr-matt-5-4":{e:`web`,t:[`Blessed are those who mourn, for they shall be comforted.`]},"pr-ps-34-18":{e:`web`,t:[`Yahweh is near to those who have a broken heart, and saves those who have a crushed spirit.`]},"pr-ps-147-3":{e:`web`,t:[`He heals the broken in heart, and binds up their wounds.`]},"pr-1pet-5-7":{e:`web`,t:[`casting all your worries on him, because he cares for you.`]},"pr-rom-15-13":{e:`web`,t:[`Now may the God of hope fill you with all joy and peace in believing, that you may abound in hope, in the power of the Holy Spirit.`]},"pr-isa-40-31":{e:`web`,t:[`but those who wait for Yahweh will renew their strength. They will mount up with wings like eagles. They will run, and not be weary. They will walk, and not faint.`]},"pr-rom-5-5":{e:`web`,t:[`and hope doesn’t disappoint us, because God’s love has been poured into our hearts through the Holy Spirit who was given to us.`]},"pr-prov-23-18":{e:`web`,t:[`Indeed surely there is a future hope, and your hope will not be cut off.`]},"pr-heb-10-23":{e:`web`,t:[`let’s hold fast the confession of our hope without wavering; for he who promised is faithful.`]},"pr-jer-29-11":{e:`web`,t:[`For I know the thoughts that I think toward you,” says Yahweh, “thoughts of peace, and not of evil, to give you hope and a future.`]},"pr-ps-103-2":{e:`web`,t:[`Praise Yahweh, my soul, and don’t forget all his benefits,`]},"pr-ps-118-24":{e:`web`,t:[`This is the day that Yahweh has made. We will rejoice and be glad in it!`]},"pr-ps-9-1":{e:`web`,t:[`I will give thanks to Yahweh with my whole heart. I will tell of all your marvelous works.`]},"pr-1chr-16-34":{e:`web`,t:[`Oh give thanks to Yahweh, for he is good, for his loving kindness endures forever.`]},"pr-prov-27-2":{e:`web`,t:[`Let another man praise you, and not your own mouth; a stranger, and not your own lips.`]},"pr-rom-12-16":{e:`web`,t:[`Be of the same mind one toward another. Don’t set your mind on high things, but associate with the humble. Don’t be wise in your own conceits.`]},"pr-1pet-5-5":{e:`web`,t:[`Likewise, you younger ones, be subject to the elder. Yes, all of you clothe yourselves with humility, to subject yourselves to one another; for “God resists the proud, but gives grace to the humble.”`]},"pr-prov-22-4":{e:`web`,t:[`The result of humility and the fear of Yahweh is wealth, honor, and life.`]},"pr-ps-56-3":{e:`web`,t:[`When I am afraid, I will put my trust in you.`]},"pr-ps-31-24":{e:`web`,t:[`Be strong, and let your heart take courage, all you who hope in Yahweh.`]},"pr-heb-13-6":{e:`web`,t:[`So that with good courage we say, “The Lord is my helper. I will not fear. What can man do to me?”`]},"pr-1chr-28-20":{e:`web`,t:[`David said to Solomon his son, “Be strong and courageous, and do it. Don’t be afraid, nor be dismayed; for Yahweh God, even my God, is with you. He will not fail you, nor forsake you, until all the work for the service of Yahweh’s house is finished.`]},"pr-mark-11-25":{e:`web`,t:[`Whenever you stand praying, forgive, if you have anything against anyone; so that your Father, who is in heaven, may also forgive you your transgressions.`]},"pr-prov-19-11":{e:`web`,t:[`The discretion of a man makes him slow to anger. It is his glory to overlook an offense.`]},"pr-1pet-4-8":{e:`web`,t:[`And above all things be earnest in your love among yourselves, for love covers a multitude of sins.`]},"pr-luke-17-4":{e:`web`,t:[`If he sins against you seven times in the day, and seven times returns, saying, ‘I repent,’ you shall forgive him.”`]},"pr-prov-3-5-6":{e:`web`,t:[`Trust in Yahweh with all your heart, and don’t lean on your own understanding.`,`In all your ways acknowledge him, and he will make your paths straight.`]},"pr-prov-15-1":{e:`web`,t:[`A gentle answer turns away wrath, but a harsh word stirs up anger.`]},"pr-prov-13-20":{e:`web`,t:[`One who walks with wise men grows wise, but a companion of fools suffers harm.`]},"pr-eccl-3-1":{e:`web`,t:[`For everything there is a season, and a time for every purpose under heaven:`]},"pr-heb-13-16":{e:`web`,t:[`But don’t forget to be doing good and sharing, for with such sacrifices God is well pleased.`]},"pr-luke-6-38":{e:`web`,t:[`“Give, and it will be given to you: good measure, pressed down, shaken together, and running over, will be given to you. For with the same measure you measure it will be measured back to you.”`]},"pr-prov-3-27":{e:`web`,t:[`Don’t withhold good from those to whom it is due, when it is in the power of your hand to do it.`]},"pr-gal-6-2":{e:`web`,t:[`Bear one another’s burdens, and so fulfill the law of Christ.`]},"pr-prov-25-16":{e:`web`,t:[`Have you found honey? Eat as much as is sufficient for you, lest you eat too much, and vomit it.`]},"pr-1tim-6-6":{e:`web`,t:[`But godliness with contentment is great gain.`]},"pr-heb-13-5":{e:`web`,t:[`Be free from the love of money, content with such things as you have, for he has said, “I will in no way leave you, neither will I in any way forsake you.”`]},"pr-prov-21-23":{e:`web`,t:[`Whoever guards his mouth and his tongue keeps his soul from troubles.`]},"pr-prov-10-4":{e:`web`,t:[`He becomes poor who works with a lazy hand, but the hand of the diligent brings wealth.`]},"pr-luke-16-10":{e:`web`,t:[`He who is faithful in a very little is faithful also in much. He who is dishonest in a very little is also dishonest in much.`]},"pr-prov-22-29":{e:`web`,t:[`Do you see a man skilled in his work? He will serve kings. He won’t serve obscure men.`]},"pr-prov-12-24":{e:`web`,t:[`The hands of the diligent ones shall rule, but laziness ends in slave labor.`]},"pr-rom-5-3-4":{e:`web`,t:[`Not only this, but we also rejoice in our sufferings, knowing that suffering produces perseverance;`,`and perseverance, proven character; and proven character, hope:`]},"pr-jas-1-2-3":{e:`web`,t:[`Count it all joy, my brothers, when you fall into various temptations,`,`knowing that the testing of your faith produces endurance.`]},"pr-ps-40-1":{e:`web`,t:[`I waited patiently for Yahweh. He turned to me, and heard my cry.`]},"pr-lam-3-25-26":{e:`web`,t:[`Yahweh is good to those who wait for him, to the soul who seeks him.`,`It is good that a man should hope and quietly wait for the salvation of Yahweh.`]},"pr-ps-23-1-2":{e:`web`,t:[`Yahweh is my shepherd: I shall lack nothing.`,`He makes me lie down in green pastures. He leads me beside still waters.`]},"pr-num-6-24-26":{e:`web`,t:[`‘Yahweh bless you, and keep you.`,`Yahweh make his face to shine on you, and be gracious to you.`,`Yahweh lift up his face toward you, and give you peace.’`]},"pr-phil-4-7":{e:`web`,t:[`And the peace of God, which surpasses all understanding, will guard your hearts and your thoughts in Christ Jesus.`]},"pr-2thess-3-16":{e:`web`,t:[`Now may the Lord of peace himself give you peace at all times in all ways. The Lord be with you all.`]},"pr-ps-46-1":{e:`web`,t:[`God is our refuge and strength, a very present help in trouble.`]},"pr-matt-6-34":{e:`web`,t:[`Therefore don’t be anxious for tomorrow, for tomorrow will be anxious for itself. Each day’s own evil is sufficient.`]},"pr-isa-40-29":{e:`web`,t:[`He gives power to the weak. He increases the strength of him who has no might.`]},"pr-ps-55-22":{e:`web`,t:[`Cast your burden on Yahweh and he will sustain you. He will never allow the righteous to be moved.`]},"pr-rom-8-28":{e:`web`,t:[`We know that all things work together for good for those who love God, for those who are called according to his purpose.`]},"pr-ps-42-11":{e:`web`,t:[`Why are you in despair, my soul? Why are you disturbed within me? Hope in God! For I shall still praise him, the saving help of my countenance, and my God.`]},"pr-isa-43-19":{e:`web`,t:[`Behold, I will do a new thing. It springs out now. Don’t you know it? I will even make a way in the wilderness, and rivers in the desert.`]},"pr-heb-11-1":{e:`web`,t:[`Now faith is assurance of things hoped for, proof of things not seen.`]},"pr-ps-95-2":{e:`web`,t:[`Let’s come before his presence with thanksgiving. Let’s extol him with songs!`]},"pr-ps-92-1":{e:`web`,t:[`It is a good thing to give thanks to Yahweh, to sing praises to your name, Most High,`]},"pr-ps-126-3":{e:`web`,t:[`Yahweh has done great things for us, and we are glad.`]},"pr-eph-5-20":{e:`web`,t:[`giving thanks always concerning all things in the name of our Lord Jesus Christ, to God, even the Father;`]},"pr-col-3-17":{e:`web`,t:[`Whatever you do, in word or in deed, do all in the name of the Lord Jesus, giving thanks to God the Father, through him.`]},"pr-1th-5-16":{e:`web`,t:[`Always rejoice.`]},"pr-ps-28-7":{e:`web`,t:[`Yahweh is my strength and my shield. My heart has trusted in him, and I am helped. Therefore my heart greatly rejoices. With my song I will thank him.`]},"pr-hab-3-17-18":{e:`web`,t:[`For though the fig tree doesn’t flourish, nor fruit be in the vines; the labor of the olive fails, the fields yield no food; the flocks are cut off from the fold, and there is no herd in the stalls:`,`yet I will rejoice in Yahweh. I will be joyful in the God of my salvation!`]},"pr-prov-16-18":{e:`web`,t:[`Pride goes before destruction, and an arrogant spirit before a fall.`]},"pr-prov-15-33":{e:`web`,t:[`The fear of Yahweh teaches wisdom. Before honor is humility.`]},"pr-jas-4-6":{e:`web`,t:[`But he gives more grace. Therefore it says, “God resists the proud, but gives grace to the humble.”`]},"pr-phil-2-4":{e:`web`,t:[`each of you not just looking to his own things, but each of you also to the things of others.`]},"pr-gal-6-3":{e:`web`,t:[`For if a man thinks himself to be something when he is nothing, he deceives himself.`]},"pr-rom-12-3":{e:`web`,t:[`For I say through the grace that was given me, to every man who is among you, not to think of himself more highly than he ought to think; but to think reasonably, as God has apportioned to each person a measure of faith.`]},"pr-prov-29-23":{e:`web`,t:[`A man’s pride brings him low, but one of lowly spirit gains honor.`]},"pr-matt-5-5":{e:`web`,t:[`Blessed are the gentle, for they shall inherit the earth.`]},"pr-ps-27-1":{e:`web`,t:[`Yahweh is my light and my salvation. Whom shall I fear? Yahweh is the strength of my life. Of whom shall I be afraid?`]},"pr-isa-43-1":{e:`web`,t:[`But now Yahweh who created you, Jacob, and he who formed you, Israel, says: “Don’t be afraid, for I have redeemed you. I have called you by your name. You are mine.`]},"pr-ps-118-6":{e:`web`,t:[`Yahweh is on my side. I will not be afraid. What can man do to me?`]},"pr-eph-6-10":{e:`web`,t:[`Finally, be strong in the Lord, and in the strength of his might.`]},"pr-isa-12-2":{e:`web`,t:[`Behold, God is my salvation. I will trust, and will not be afraid; for Yah, Yahweh, is my strength and song; and he has become my salvation.”`]},"pr-ps-121-1-2":{e:`web`,t:[`I will lift up my eyes to the hills. Where does my help come from?`,`My help comes from Yahweh, who made heaven and earth.`]},"pr-prov-28-1":{e:`web`,t:[`The wicked flee when no one pursues; but the righteous are as bold as a lion.`]},"pr-matt-14-27":{e:`web`,t:[`But immediately Jesus spoke to them, saying, “Cheer up! It is I! Don’t be afraid.”`]},"pr-matt-6-14":{e:`web`,t:[`“For if you forgive men their trespasses, your heavenly Father will also forgive you.`]},"pr-eph-4-26":{e:`web`,t:[`“Be angry, and don’t sin.” Don’t let the sun go down on your wrath,`]},"pr-rom-12-17":{e:`web`,t:[`Repay no one evil for evil. Respect what is honorable in the sight of all men.`]},"pr-rom-12-21":{e:`web`,t:[`Don’t be overcome by evil, but overcome evil with good.`]},"pr-1pet-3-9":{e:`web`,t:[`not rendering evil for evil, or insult for insult; but instead blessing, knowing that you were called to this, that you may inherit a blessing.`]},"pr-prov-24-29":{e:`web`,t:[`Don’t say, “I will do to him as he has done to me; I will repay the man according to his work.”`]},"pr-matt-5-23-24":{e:`web`,t:[`“If therefore you are offering your gift at the altar, and there remember that your brother has anything against you,`,`leave your gift there before the altar, and go your way. First be reconciled to your brother, and then come and offer your gift.`]},"pr-ps-103-12":{e:`web`,t:[`As far as the east is from the west, so far has he removed our transgressions from us.`]},"pr-prov-1-5":{e:`web`,t:[`that the wise man may hear, and increase in learning; that the man of understanding may attain to sound counsel:`]},"pr-prov-9-10":{e:`web`,t:[`The fear of Yahweh is the beginning of wisdom. The knowledge of the Holy One is understanding.`]},"pr-prov-18-15":{e:`web`,t:[`The heart of the discerning gets knowledge. The ear of the wise seeks knowledge.`]},"pr-eccl-4-9-10":{e:`web`,t:[`Two are better than one, because they have a good reward for their labor.`,`For if they fall, the one will lift up his fellow; but woe to him who is alone when he falls, and doesn’t have another to lift him up.`]},"pr-prov-27-17":{e:`web`,t:[`Iron sharpens iron; so a man sharpens his friend’s countenance.`]},"pr-prov-4-23":{e:`web`,t:[`Keep your heart with all diligence, for out of it is the wellspring of life.`]},"pr-col-4-6":{e:`web`,t:[`Let your speech always be with grace, seasoned with salt, that you may know how you ought to answer each one.`]},"pr-prov-12-1":{e:`web`,t:[`Whoever loves correction loves knowledge, but he who hates reproof is stupid.`]},"pr-prov-22-9":{e:`web`,t:[`He who has a generous eye will be blessed; for he shares his food with the poor.`]},"pr-deut-15-11":{e:`web`,t:[`For the poor will never cease out of the land. Therefore I command you to surely open your hand to your brother, to your needy, and to your poor, in your land.`]},"pr-isa-58-10":{e:`web`,t:[`and if you pour out your soul to the hungry, and satisfy the afflicted soul, then your light will rise in darkness, and your obscurity will be as the noonday;`]},"pr-rom-12-13":{e:`web`,t:[`contributing to the needs of the saints; given to hospitality.`]},"pr-heb-13-2":{e:`web`,t:[`Don’t forget to show hospitality to strangers, for in doing so, some have entertained angels without knowing it.`]},"pr-1pet-4-9":{e:`web`,t:[`Be hospitable to one another without grumbling.`]},"pr-luke-3-11":{e:`web`,t:[`He answered them, “He who has two coats, let him give to him who has none. He who has food, let him do likewise.”`]},"pr-prov-11-24":{e:`web`,t:[`There is one who scatters, and increases yet more. There is one who withholds more than is appropriate, but gains poverty.`]},"pr-1cor-9-25":{e:`web`,t:[`Every man who strives in the games exercises self-control in all things. Now they do it to receive a corruptible crown, but we an incorruptible.`]},"pr-prov-14-30":{e:`web`,t:[`The life of the body is a heart at peace, but envy rots the bones.`]},"pr-prov-23-4":{e:`web`,t:[`Don’t weary yourself to be rich. In your wisdom, show restraint.`]},"pr-eccl-5-10":{e:`web`,t:[`He who loves silver shall not be satisfied with silver; nor he who loves abundance, with increase: this also is vanity.`]},"pr-prov-10-19":{e:`web`,t:[`In the multitude of words there is no lack of disobedience, but he who restrains his lips does wisely.`]},"pr-phil-4-5":{e:`web`,t:[`Let your gentleness be known to all men. The Lord is at hand.`]},"pr-luke-12-15":{e:`web`,t:[`He said to them, “Beware! Keep yourselves from covetousness, for a man’s life doesn’t consist of the abundance of the things which he possesses.”`]},"pr-prov-17-27":{e:`web`,t:[`He who spares his words has knowledge. He who is even tempered is a man of understanding.`]},"pr-2tim-2-15":{e:`web`,t:[`Give diligence to present yourself approved by God, a workman who doesn’t need to be ashamed, properly handling the Word of Truth.`]},"pr-prov-14-23":{e:`web`,t:[`In all hard work there is profit, but the talk of the lips leads only to poverty.`]},"pr-prov-12-11":{e:`web`,t:[`He who tills his land shall have plenty of bread, but he who chases fantasies is void of understanding.`]},"pr-eccl-11-6":{e:`web`,t:[`In the morning sow your seed, and in the evening don’t withhold your hand; for you don’t know which will prosper, whether this or that, or whether they both will be equally good.`]},"pr-rom-12-11":{e:`web`,t:[`not lagging in diligence; fervent in spirit; serving the Lord;`]},"pr-luke-19-17":{e:`web`,t:[`“He said to him, ‘Well done, you good servant! Because you were found faithful with very little, you shall have authority over ten cities.’`]},"pr-prov-27-23":{e:`web`,t:[`Know well the state of your flocks, and pay attention to your herds:`]},"pr-1cor-10-31":{e:`web`,t:[`Whether therefore you eat, or drink, or whatever you do, do all to the glory of God.`]},"pr-heb-12-1":{e:`web`,t:[`Therefore let’s also, seeing we are surrounded by so great a cloud of witnesses, lay aside every weight and the sin which so easily entangles us, and let’s run with perseverance the race that is set before us,`]},"pr-isa-30-15":{e:`web`,t:[`For thus said the Lord Yahweh, the Holy One of Israel, “You will be saved in returning and rest. Your strength will be in quietness and in confidence.” You refused,`]},"pr-hab-2-3":{e:`web`,t:[`For the vision is yet for the appointed time, and it hurries toward the end, and won’t prove false. Though it takes time, wait for it; because it will surely come. It won’t delay.`]},"pr-heb-10-36":{e:`web`,t:[`For you need endurance so that, having done the will of God, you may receive the promise.`]},"pr-col-3-12":{e:`web`,t:[`Put on therefore, as God’s chosen ones, holy and beloved, a heart of compassion, kindness, lowliness, humility, and perseverance;`]},"pr-prov-25-15":{e:`web`,t:[`By patience a ruler is persuaded. A soft tongue breaks the bone.`]},"pr-eccl-7-9":{e:`web`,t:[`Don’t be hasty in your spirit to be angry, for anger rests in the bosom of fools.`]},"pr-1th-5-14":{e:`web`,t:[`We exhort you, brothers: Admonish the disorderly; encourage the faint-hearted; support the weak; be patient toward all.`]},"pr-ps-29-11":{e:`web`,t:[`Yahweh will give strength to his people. Yahweh will bless his people with peace.`]},"pr-ps-91-1-2":{e:`web`,t:[`He who dwells in the secret place of the Most High will rest in the shadow of the Almighty.`,`I will say of Yahweh, “He is my refuge and my fortress; my God, in whom I trust.”`]},"pr-2cor-13-11":{e:`web`,t:[`Finally, brothers, rejoice! Be perfected. Be comforted. Be of the same mind. Live in peace, and the God of love and peace will be with you.`]},"pr-isa-32-17":{e:`web`,t:[`The work of righteousness will be peace, and the effect of righteousness, quietness and confidence forever.`]},"pr-ps-46-10":{e:`web`,t:[`“Be still, and know that I am God. I will be exalted among the nations. I will be exalted in the earth.”`]},"pr-ps-119-165":{e:`web`,t:[`Those who love your law have great peace. Nothing causes them to stumble.`]},"pr-matt-11-29":{e:`web`,t:[`Take my yoke upon you, and learn from me, for I am gentle and humble in heart; and you will find rest for your souls.`]},"pr-ps-16-8":{e:`web`,t:[`I have set Yahweh always before me. Because he is at my right hand, I shall not be moved.`]},"pr-isa-41-13":{e:`web`,t:[`For I, Yahweh your God, will hold your right hand, saying to you, ‘Don’t be afraid. I will help you.’`]},"pr-ps-30-5":{e:`web`,t:[`For his anger is but for a moment. His favor is for a lifetime. Weeping may stay for the night, but joy comes in the morning.`]},"pr-isa-66-13":{e:`web`,t:[`As one whom his mother comforts, so I will comfort you. You will be comforted in Jerusalem.”`]},"pr-ps-73-26":{e:`web`,t:[`My flesh and my heart fails, but God is the strength of my heart and my portion forever.`]},"pr-john-14-1":{e:`web`,t:[`“Don’t let your heart be troubled. Believe in God. Believe also in me.`]},"pr-2cor-4-16":{e:`web`,t:[`Therefore we don’t faint, but though our outward man is decaying, yet our inward man is renewed day by day.`]},"pr-ps-94-19":{e:`web`,t:[`In the multitude of my thoughts within me, your comforts delight my soul.`]},"pr-prov-17-22":{e:`web`,t:[`A cheerful heart makes good medicine, but a crushed spirit dries up the bones.`]},"pr-ps-62-5":{e:`web`,t:[`My soul, wait in silence for God alone, for my expectation is from him.`]},"pr-lam-3-22-23":{e:`web`,t:[`It is because of Yahweh’s loving kindnesses that we are not consumed, because his compassion doesn’t fail.`,`They are new every morning. Great is your faithfulness.`]},"pr-ps-33-20":{e:`web`,t:[`Our soul has waited for Yahweh. He is our help and our shield.`]},"pr-mic-7-7":{e:`web`,t:[`But as for me, I will look to Yahweh. I will wait for the God of my salvation. My God will hear me.`]},"pr-phil-1-6":{e:`web`,t:[`being confident of this very thing, that he who began a good work in you will complete it until the day of Jesus Christ.`]},"pr-prov-13-12":{e:`web`,t:[`Hope deferred makes the heart sick, but when longing is fulfilled, it is a tree of life.`]},"pr-1cor-13-13":{e:`web`,t:[`But now faith, hope, and love remain—these three. The greatest of these is love.`]},"pr-ps-71-14":{e:`web`,t:[`But I will always hope, and will add to all of your praise.`]},"pr-prov-3-3":{e:`web`,t:[`Don’t let kindness and truth forsake you. Bind them around your neck. Write them on the tablet of your heart.`]},"pr-eph-4-29":{e:`web`,t:[`Let no corrupt speech proceed out of your mouth, but only what is good for building others up as the need may be, that it may give grace to those who hear.`]},"pr-prov-16-3":{e:`web`,t:[`Commit your deeds to Yahweh, and your plans shall succeed.`]},"pr-ps-37-5":{e:`web`,t:[`Commit your way to Yahweh. Trust also in him, and he will do this:`]},"pr-ps-111-1":{e:`web`,t:[`Praise Yah! I will give thanks to Yahweh with my whole heart, in the council of the upright, and in the congregation.`]},"pr-ps-145-9":{e:`web`,t:[`Yahweh is good to all. His tender mercies are over all his works.`]},"pr-ps-147-7":{e:`web`,t:[`Sing to Yahweh with thanksgiving. Sing praises on the harp to our God,`]},"pr-ps-104-24":{e:`web`,t:[`Yahweh, how many are your works! In wisdom, you have made them all. The earth is full of your riches.`]},"pr-2cor-9-15":{e:`web`,t:[`Now thanks be to God for his unspeakable gift!`]},"pr-1tim-4-4":{e:`web`,t:[`For every creature of God is good, and nothing is to be rejected, if it is received with thanksgiving.`]},"pr-luke-17-15-16":{e:`web`,t:[`One of them, when he saw that he was healed, turned back, glorifying God with a loud voice.`,`He fell on his face at Jesus’ feet, giving him thanks; and he was a Samaritan.`]},"pr-col-2-7":{e:`web`,t:[`rooted and built up in him, and established in the faith, even as you were taught, abounding in it in thanksgiving.`]},"pr-prov-18-12":{e:`web`,t:[`Before destruction the heart of man is proud, but before honor is humility.`]},"pr-prov-16-19":{e:`web`,t:[`It is better to be of a lowly spirit with the poor, than to divide the plunder with the proud.`]},"pr-1pet-5-6":{e:`web`,t:[`Humble yourselves therefore under the mighty hand of God, that he may exalt you in due time,`]},"pr-mark-9-35":{e:`web`,t:[`He sat down, and called the twelve; and he said to them, “If any man wants to be first, he shall be last of all, and servant of all.”`]},"pr-john-13-14":{e:`web`,t:[`If I then, the Lord and the Teacher, have washed your feet, you also ought to wash one another’s feet.`]},"pr-jas-3-13":{e:`web`,t:[`Who is wise and understanding among you? Let him show by his good conduct that his deeds are done in gentleness of wisdom.`]},"pr-rom-12-10":{e:`web`,t:[`In love of the brothers be tenderly affectionate to one another; in honor preferring one another;`]},"pr-matt-18-4":{e:`web`,t:[`Whoever therefore humbles himself as this little child is the greatest in the Kingdom of Heaven.`]},"pr-deut-31-8":{e:`web`,t:[`Yahweh himself is who goes before you. He will be with you. He will not fail you nor forsake you. Don’t be afraid. Don’t be discouraged.”`]},"pr-2chr-15-7":{e:`web`,t:[`But you be strong, and don’t let your hands be slack; for your work will be rewarded.”`]},"pr-acts-27-25":{e:`web`,t:[`Therefore, sirs, cheer up! For I believe God, that it will be just as it has been spoken to me.`]},"pr-josh-1-7":{e:`web`,t:[`Only be strong and very courageous. Be careful to observe to do according to all the law which Moses my servant commanded you. Don’t turn from it to the right hand or to the left, that you may have good success wherever you go.`]},"pr-heb-4-16":{e:`web`,t:[`Let’s therefore draw near with boldness to the throne of grace, that we may receive mercy and may find grace for help in time of need.`]},"pr-mark-9-23":{e:`web`,t:[`Jesus said to him, “If you can believe, all things are possible to him who believes.”`]},"pr-2cor-12-9":{e:`web`,t:[`He has said to me, “My grace is sufficient for you, for my power is made perfect in weakness.” Most gladly therefore I will rather glory in my weaknesses, that the power of Christ may rest on me.`]},"pr-phil-4-13":{e:`web`,t:[`I can do all things through Christ, who strengthens me.`]},"pr-matt-5-44":{e:`web`,t:[`But I tell you, love your enemies, bless those who curse you, do good to those who hate you, and pray for those who mistreat you and persecute you,`]},"pr-prov-20-22":{e:`web`,t:[`Don’t say, “I will pay back evil.” Wait for Yahweh, and he will save you.`]},"pr-1cor-13-5":{e:`web`,t:[`doesn’t behave itself inappropriately, doesn’t seek its own way, is not provoked, takes no account of evil;`]},"pr-2cor-2-7":{e:`web`,t:[`so that on the contrary you should rather forgive him and comfort him, lest by any means such a one should be swallowed up with his excessive sorrow.`]},"pr-ps-86-5":{e:`web`,t:[`For you, Lord, are good, and ready to forgive, abundant in loving kindness to all those who call on you.`]},"pr-eph-4-31":{e:`web`,t:[`Let all bitterness, wrath, anger, outcry, and slander be put away from you, with all malice.`]},"pr-1jn-1-9":{e:`web`,t:[`If we confess our sins, he is faithful and righteous to forgive us the sins, and to cleanse us from all unrighteousness.`]},"pr-jas-5-16":{e:`web`,t:[`Confess your offenses to one another, and pray for one another, that you may be healed. The insistent prayer of a righteous person is powerfully effective.`]},"pr-matt-6-12":{e:`web`,t:[`Forgive us our debts, as we also forgive our debtors.`]},"pr-prov-2-6":{e:`web`,t:[`For Yahweh gives wisdom. Out of his mouth comes knowledge and understanding.`]},"pr-prov-4-7":{e:`web`,t:[`Wisdom is supreme. Get wisdom. Yes, though it costs all your possessions, get understanding.`]},"pr-prov-15-22":{e:`web`,t:[`Where there is no counsel, plans fail; but in a multitude of counselors they are established.`]},"pr-prov-20-5":{e:`web`,t:[`Counsel in the heart of man is like deep water, but a man of understanding will draw it out.`]},"pr-prov-18-13":{e:`web`,t:[`He who answers before he hears, that is folly and shame to him.`]},"pr-ps-119-105":{e:`web`,t:[`Your word is a lamp to my feet, and a light for my path.`]},"pr-ps-32-8":{e:`web`,t:[`I will instruct you and teach you in the way which you shall go. I will counsel you with my eye on you.`]},"pr-matt-7-24":{e:`web`,t:[`“Everyone therefore who hears these words of mine, and does them, I will liken him to a wise man, who built his house on a rock.`]},"pr-prov-14-15":{e:`web`,t:[`A simple man believes everything, but the prudent man carefully considers his ways.`]},"pr-2cor-9-6":{e:`web`,t:[`Remember this: he who sows sparingly will also reap sparingly. He who sows bountifully will also reap bountifully.`]},"pr-1tim-6-18":{e:`web`,t:[`that they do good, that they be rich in good works, that they be ready to distribute, willing to share;`]},"pr-isa-58-7":{e:`web`,t:[`Isn’t it to distribute your bread to the hungry, and that you bring the poor who are cast out to your house? When you see the naked, that you cover him; and that you not hide yourself from your own flesh?`]},"pr-deut-15-10":{e:`web`,t:[`You shall surely give, and your heart shall not be grieved when you give to him, because it is for this thing Yahweh your God will bless you in all your work and in all that you put your hand to.`]},"pr-prov-14-21":{e:`web`,t:[`He who despises his neighbor sins, but he who has pity on the poor is blessed.`]},"pr-1pet-4-10":{e:`web`,t:[`As each has received a gift, employ it in serving one another, as good managers of the grace of God in its various forms.`]},"pr-gal-6-10":{e:`web`,t:[`So then, as we have opportunity, let’s do what is good toward all men, and especially toward those who are of the household of the faith.`]},"pr-heb-6-10":{e:`web`,t:[`For God is not unrighteous, so as to forget your work and the labor of love which you showed toward his name, in that you served the saints, and still do serve them.`]},"pr-1tim-6-8":{e:`web`,t:[`But having food and clothing, we will be content with that.`]},"pr-1th-4-11":{e:`web`,t:[`and that you make it your ambition to lead a quiet life, and to do your own business, and to work with your own hands, even as we instructed you;`]},"pr-rom-13-13":{e:`web`,t:[`Let’s walk properly, as in the day; not in reveling and drunkenness, not in sexual promiscuity and lustful acts, and not in strife and jealousy.`]},"pr-eph-5-18":{e:`web`,t:[`Don’t be drunken with wine, in which is dissipation, but be filled with the Spirit,`]},"pr-prov-17-28":{e:`web`,t:[`Even a fool, when he keeps silent, is counted wise. When he shuts his lips, he is thought to be discerning.`]},"pr-jas-3-5":{e:`web`,t:[`So the tongue is also a little member, and boasts great things. See how a small fire can spread to a large forest!`]},"pr-1cor-6-12":{e:`web`,t:[`“All things are lawful for me,” but not all things are expedient. “All things are lawful for me,” but I will not be brought under the power of anything.`]},"pr-phil-4-11-12":{e:`web`,t:[`Not that I speak because of lack, for I have learned in whatever state I am, to be content in it.`,`I know how to be humbled, and I also know how to abound. In everything and in all things I have learned the secret both to be filled and to be hungry, both to abound and to be in need.`]},"pr-prov-10-9":{e:`web`,t:[`He who walks blamelessly walks surely, but he who perverts his ways will be found out.`]},"pr-prov-12-22":{e:`web`,t:[`Lying lips are an abomination to Yahweh, but those who do the truth are his delight.`]},"pr-matt-5-37":{e:`web`,t:[`But let your ‘Yes’ be ‘Yes’ and your ‘No’ be ‘No.’ Whatever is more than these is of the evil one.`]},"pr-1cor-4-2":{e:`web`,t:[`Here, moreover, it is required of stewards that they be found faithful.`]},"pr-2cor-8-11":{e:`web`,t:[`But now complete the doing also, that as there was the readiness to be willing, so there may be the completion also out of your ability.`]},"pr-ps-15-2":{e:`web`,t:[`He who walks blamelessly and does what is right, and speaks truth in his heart;`]},"pr-zech-8-16":{e:`web`,t:[`These are the things that you shall do: speak every man the truth with his neighbor. Execute the judgment of truth and peace in your gates,`]},"pr-jas-1-22":{e:`web`,t:[`But be doers of the word, and not only hearers, deluding your own selves.`]},"pr-2thess-3-13":{e:`web`,t:[`But you, brothers, don’t be weary in doing what is right.`]},"pr-1cor-13-7":{e:`web`,t:[`bears all things, believes all things, hopes all things, and endures all things.`]},"pr-jas-5-11":{e:`web`,t:[`Behold, we call them blessed who endured. You have heard of the perseverance of Job, and have seen the Lord in the outcome, and how the Lord is full of compassion and mercy.`]},"pr-rom-8-25":{e:`web`,t:[`But if we hope for that which we don’t see, we wait for it with patience.`]},"pr-heb-6-12":{e:`web`,t:[`that you won’t be sluggish, but imitators of those who through faith and perseverance inherited the promises.`]},"pr-2thess-3-5":{e:`web`,t:[`May the Lord direct your hearts into God’s love, and into the perseverance of Christ.`]},"pr-luke-8-15":{e:`web`,t:[`Those in the good ground, these are those who with an honest and good heart, having heard the word, hold it tightly, and produce fruit with perseverance.`]},"pr-col-1-11":{e:`web`,t:[`strengthened with all power, according to the might of his glory, for all endurance and perseverance with joy,`]},"pr-heb-6-15":{e:`web`,t:[`Thus, having patiently endured, he obtained the promise.`]},"pr-rom-14-19":{e:`web`,t:[`So then, let’s follow after things which make for peace, and things by which we may build one another up.`]},"pr-1pet-3-11":{e:`web`,t:[`Let him turn away from evil and do good. Let him seek peace and pursue it.`]},"pr-mark-9-50":{e:`web`,t:[`Salt is good, but if the salt has lost its saltiness, with what will you season it? Have salt in yourselves, and be at peace with one another.”`]},"pr-prov-15-17":{e:`web`,t:[`Better is a dinner of herbs, where love is, than a fattened calf with hatred.`]},"pr-prov-17-1":{e:`web`,t:[`Better is a dry morsel with quietness, than a house full of feasting with strife.`]},"pr-jas-3-18":{e:`web`,t:[`Now the fruit of righteousness is sown in peace by those who make peace.`]},"pr-ps-116-7":{e:`web`,t:[`Return to your rest, my soul, for Yahweh has dealt bountifully with you.`]},"pr-phil-4-9":{e:`web`,t:[`The things which you learned, received, heard, and saw in me: do these things, and the God of peace will be with you.`]},"pr-mark-4-39":{e:`web`,t:[`He awoke, and rebuked the wind, and said to the sea, “Peace! Be still!” The wind ceased, and there was a great calm.`]},"pr-rom-12-15":{e:`web`,t:[`Rejoice with those who rejoice. Weep with those who weep.`]},"pr-ps-121-3":{e:`web`,t:[`He will not allow your foot to be moved. He who keeps you will not slumber.`]},"pr-ps-121-8":{e:`web`,t:[`Yahweh will keep your going out and your coming in, from this time forward, and forever more.`]},"pr-isa-46-4":{e:`web`,t:[`Even to old age I am he, and even to gray hairs I will carry you. I have made, and I will bear. Yes, I will carry, and will deliver.`]},"pr-ps-145-14":{e:`web`,t:[`Yahweh upholds all who fall, and raises up all those who are bowed down.`]},"pr-ps-145-18":{e:`web`,t:[`Yahweh is near to all those who call on him, to all who call on him in truth.`]},"pr-2cor-7-6":{e:`web`,t:[`Nevertheless, he who comforts the lowly, God, comforted us by the coming of Titus,`]},"pr-isa-49-15":{e:`web`,t:[`“Can a woman forget her nursing child, that she should not have compassion on the son of her womb? Yes, these may forget, yet I will not forget you!`]},"pr-prov-24-14":{e:`web`,t:[`so you shall know wisdom to be to your soul. If you have found it, then there will be a reward: Your hope will not be cut off.`]},"pr-ps-71-5":{e:`web`,t:[`For you are my hope, Lord Yahweh, my confidence from my youth.`]},"pr-ps-146-5":{e:`web`,t:[`Happy is he who has the God of Jacob for his help, whose hope is in Yahweh, his God:`]},"pr-ps-147-11":{e:`web`,t:[`Yahweh takes pleasure in those who fear him, in those who hope in his loving kindness.`]},"pr-matt-7-7":{e:`web`,t:[`“Ask, and it will be given you. Seek, and you will find. Knock, and it will be opened for you.`]},"pr-luke-1-37":{e:`web`,t:[`For nothing spoken by God is impossible.”`]},"pr-phil-3-13-14":{e:`web`,t:[`Brothers, I don’t regard myself as yet having taken hold, but one thing I do: forgetting the things which are behind, and stretching forward to the things which are before,`,`I press on toward the goal for the prize of the high calling of God in Christ Jesus.`]},"pr-heb-6-19":{e:`web`,t:[`This hope we have as an anchor of the soul, a hope both sure and steadfast and entering into that which is within the veil;`]},"pr-ps-100-5":{e:`web`,t:[`For Yahweh is good. His loving kindness endures forever, his faithfulness to all generations.`]},"pr-1chr-16-8":{e:`web`,t:[`Oh give thanks to Yahweh. Call on his name. Make what he has done known among the peoples.`]},"pr-ps-118-1":{e:`web`,t:[`Give thanks to Yahweh, for he is good, for his loving kindness endures forever.`]},"pr-col-3-16":{e:`web`,t:[`Let the word of Christ dwell in you richly; in all wisdom teaching and admonishing one another with psalms, hymns, and spiritual songs, singing with grace in your heart to the Lord.`]},"pr-heb-12-28":{e:`web`,t:[`Therefore, receiving a Kingdom that can’t be shaken, let’s have grace, through which we serve God acceptably, with reverence and awe,`]},"pr-2cor-4-15":{e:`web`,t:[`For all things are for your sakes, that the grace, being multiplied through the many, may cause the thanksgiving to abound to the glory of God.`]},"pr-luke-1-46-47":{e:`web`,t:[`Mary said, “My soul magnifies the Lord.`,`My spirit has rejoiced in God my Savior,`]},"pr-prov-3-7":{e:`web`,t:[`Don’t be wise in your own eyes. Fear Yahweh, and depart from evil.`]},"pr-matt-23-11":{e:`web`,t:[`But he who is greatest among you will be your servant.`]},"pr-1cor-4-7":{e:`web`,t:[`For who makes you different? And what do you have that you didn’t receive? But if you did receive it, why do you boast as if you had not received it?`]},"pr-prov-25-6-7":{e:`web`,t:[`Don’t exalt yourself in the presence of the king, or claim a place among great men;`,`for it is better that it be said to you, “Come up here,” than that you should be put lower in the presence of the prince, whom your eyes have seen.`]},"pr-isa-66-2":{e:`web`,t:[`For my hand has made all these things, and so all these things came to be,” says Yahweh: “but I will look to this man, even to he who is poor and of a contrite spirit, and who trembles at my word.`]},"pr-1pet-3-8":{e:`web`,t:[`Finally, all of you be like-minded, compassionate, loving as brothers, tenderhearted, courteous,`]},"pr-prov-15-31":{e:`web`,t:[`The ear that listens to reproof lives, and will be at home among the wise.`]},"pr-1jn-4-18":{e:`web`,t:[`There is no fear in love; but perfect love casts out fear, because fear has punishment. He who fears is not made perfect in love.`]},"pr-matt-10-31":{e:`web`,t:[`Therefore don’t be afraid. You are of more value than many sparrows.`]},"pr-luke-12-32":{e:`web`,t:[`Don’t be afraid, little flock, for it is your Father’s good pleasure to give you the Kingdom.`]},"pr-2cor-4-8-9":{e:`web`,t:[`We are pressed on every side, yet not crushed; perplexed, yet not to despair;`,`pursued, yet not forsaken; struck down, yet not destroyed;`]},"pr-neh-8-10":{e:`web`,t:[`Then he said to them, “Go your way. Eat the fat, drink the sweet, and send portions to him for whom nothing is prepared, for today is holy to our Lord. Don’t be grieved, for the joy of Yahweh is your strength.”`]},"pr-acts-23-11":{e:`web`,t:[`The following night, the Lord stood by him and said, “Cheer up, Paul, for as you have testified about me at Jerusalem, so you must testify also at Rome.”`]},"pr-isa-43-5":{e:`web`,t:[`Don’t be afraid, for I am with you. I will bring your offspring from the east, and gather you from the west.`]},"pr-luke-15-20":{e:`web`,t:[`“He arose, and came to his father. But while he was still far off, his father saw him, and was moved with compassion, and ran, and fell on his neck, and kissed him.`]},"pr-mic-7-19":{e:`web`,t:[`He will again have compassion on us. He will tread our iniquities under foot; and you will cast all their sins into the depths of the sea.`]},"pr-ps-32-5":{e:`web`,t:[`I acknowledged my sin to you. I didn’t hide my iniquity. I said, I will confess my transgressions to Yahweh, and you forgave the iniquity of my sin.`]},"pr-ps-103-10":{e:`web`,t:[`He has not dealt with us according to our sins, nor repaid us for our iniquities.`]},"pr-isa-43-25":{e:`web`,t:[`I, even I, am he who blots out your transgressions for my own sake; and I will not remember your sins.`]},"pr-gen-50-20-21":{e:`web`,t:[`As for you, you meant evil against me, but God meant it for good, to save many people alive, as is happening today.`,`Now therefore don’t be afraid. I will provide for you and your little ones.” He comforted them, and spoke kindly to them.`]},"pr-prov-1-7":{e:`web`,t:[`The fear of Yahweh is the beginning of knowledge; but the foolish despise wisdom and instruction.`]},"pr-prov-3-13":{e:`web`,t:[`Happy is the man who finds wisdom, the man who gets understanding.`]},"pr-prov-11-14":{e:`web`,t:[`Where there is no wise guidance, the nation falls, but in the multitude of counselors there is victory.`]},"pr-prov-19-2":{e:`web`,t:[`It isn’t good to have zeal without knowledge, nor being hasty with one’s feet and missing the way.`]},"pr-prov-24-5":{e:`web`,t:[`A wise man has great power; and a knowledgeable man increases strength;`]},"pr-matt-10-16":{e:`web`,t:[`“Behold, I send you out as sheep among wolves. Therefore be wise as serpents, and harmless as doves.`]},"pr-matt-5-42":{e:`web`,t:[`Give to him who asks you, and don’t turn away him who desires to borrow from you.`]},"pr-rom-15-1-2":{e:`web`,t:[`Now we who are strong ought to bear the weaknesses of the weak, and not to please ourselves.`,`Let each one of us please his neighbor for that which is good, to be building him up.`]},"pr-prov-14-31":{e:`web`,t:[`He who oppresses the poor shows contempt for his Maker, but he who is kind to the needy honors him.`]},"pr-heb-10-24":{e:`web`,t:[`Let’s consider how to provoke one another to love and good works,`]},"pr-1jn-4-11":{e:`web`,t:[`Beloved, if God loved us in this way, we also ought to love one another.`]},"pr-jas-2-15-16":{e:`web`,t:[`And if a brother or sister is naked and in lack of daily food,`,`and one of you tells them, “Go in peace. Be warmed and filled;” yet you didn’t give them the things the body needs, what good is it?`]},"pr-luke-10-36-37":{e:`web`,t:[`Now which of these three do you think seemed to be a neighbor to him who fell among the robbers?”`,`He said, “He who showed mercy on him.” Then Jesus said to him, “Go and do likewise.”`]},"pr-prov-25-27":{e:`web`,t:[`It is not good to eat much honey, nor is it honorable to seek one’s own honor.`]},"pr-prov-20-1":{e:`web`,t:[`Wine is a mocker and beer is a brawler. Whoever is led astray by them is not wise.`]},"pr-jas-1-26":{e:`web`,t:[`If anyone among you thinks himself to be religious while he doesn’t bridle his tongue, but deceives his heart, this man’s religion is worthless.`]},"pr-prov-21-17":{e:`web`,t:[`He who loves pleasure will be a poor man. He who loves wine and oil won’t be rich.`]},"pr-matt-6-19-20":{e:`web`,t:[`“Don’t lay up treasures for yourselves on the earth, where moth and rust consume, and where thieves break through and steal;`,`but lay up for yourselves treasures in heaven, where neither moth nor rust consume, and where thieves don’t break through and steal;`]},"pr-2pet-1-5-6":{e:`web`,t:[`Yes, and for this very cause adding on your part all diligence, in your faith supply moral excellence; and in moral excellence, knowledge;`,`and in knowledge, self-control; and in self-control perseverance; and in perseverance godliness;`]},"pr-prov-22-1":{e:`web`,t:[`A good name is more desirable than great riches, and loving favor is better than silver and gold.`]},"pr-neh-6-3":{e:`web`,t:[`I sent messengers to them, saying, “I am doing a great work, so that I can’t come down. Why should the work cease, while I leave it, and come down to you?”`]},"pr-prov-11-1":{e:`web`,t:[`A false balance is an abomination to Yahweh, but accurate weights are his delight.`]},"pr-prov-12-19":{e:`web`,t:[`Truth’s lips will be established forever, but a lying tongue is only momentary.`]},"pr-eph-4-25":{e:`web`,t:[`Therefore putting away falsehood, speak truth each one with his neighbor. For we are members of one another.`]},"pr-2tim-2-6":{e:`web`,t:[`The farmer who labors must be the first to get a share of the crops.`]},"pr-prov-13-11":{e:`web`,t:[`Wealth gained dishonestly dwindles away, but he who gathers by hand makes it grow.`]},"pr-jas-1-4":{e:`web`,t:[`Let endurance have its perfect work, that you may be perfect and complete, lacking in nothing.`]},"pr-isa-30-18":{e:`web`,t:[`Therefore Yahweh will wait, that he may be gracious to you; and therefore he will be exalted, that he may have mercy on you, for Yahweh is a God of justice. Blessed are all those who wait for him.`]},"pr-rom-15-4":{e:`web`,t:[`For whatever things were written before were written for our learning, that through perseverance and through encouragement of the Scriptures we might have hope.`]},"pr-eccl-3-11":{e:`web`,t:[`He has made everything beautiful in its time. He has also set eternity in their hearts, yet so that man can’t find out the work that God has done from the beginning even to the end.`]},"pr-heb-10-35":{e:`web`,t:[`Therefore don’t throw away your boldness, which has a great reward.`]},"pr-1th-1-3":{e:`web`,t:[`remembering without ceasing your work of faith and labor of love and perseverance of hope in our Lord Jesus Christ, before our God and Father.`]},"pr-hos-6-3":{e:`web`,t:[`Let’s acknowledge Yahweh. Let’s press on to know Yahweh. As surely as the sun rises, Yahweh will appear. He will come to us like the rain, like the spring rain that waters the earth.”`]},"pr-isa-48-18":{e:`web`,t:[`Oh that you had listened to my commandments! Then your peace would have been like a river and your righteousness like the waves of the sea.`]},"pr-prov-3-24":{e:`web`,t:[`When you lie down, you will not be afraid. Yes, you will lie down, and your sleep will be sweet.`]},"pr-ps-127-2":{e:`web`,t:[`It is vain for you to rise up early, to stay up late, eating the bread of toil, for he gives sleep to his loved ones.`]},"pr-matt-6-26":{e:`web`,t:[`See the birds of the sky, that they don’t sow, neither do they reap, nor gather into barns. Your heavenly Father feeds them. Aren’t you of much more value than they?`]},"pr-prov-16-7":{e:`web`,t:[`When a man’s ways please Yahweh, he makes even his enemies to be at peace with him.`]},"pr-ps-23-3":{e:`web`,t:[`He restores my soul. He guides me in the paths of righteousness for his name’s sake.`]},"pr-matt-6-28-29":{e:`web`,t:[`Why are you anxious about clothing? Consider the lilies of the field, how they grow. They don’t toil, neither do they spin,`,`yet I tell you that even Solomon in all his glory was not dressed like one of these.`]},"pr-john-14-18":{e:`web`,t:[`I will not leave you orphans. I will come to you.`]},"pr-1cor-10-13":{e:`web`,t:[`No temptation has taken you except what is common to man. God is faithful, who will not allow you to be tempted above what you are able, but will with the temptation also make the way of escape, that you may be able to endure it.`]},"pr-zeph-3-17":{e:`web`,t:[`Yahweh, your God, is among you, a mighty one who will save. He will rejoice over you with joy. He will calm you in his love. He will rejoice over you with singing.`]},"pr-jer-31-13":{e:`web`,t:[`Then the virgin will rejoice in the dance; the young men and the old together; for I will turn their mourning into joy, and will comfort them, and make them rejoice from their sorrow.`]},"pr-john-16-22":{e:`web`,t:[`Therefore you now have sorrow, but I will see you again, and your heart will rejoice, and no one will take your joy away from you.`]},"pr-isa-57-15":{e:`web`,t:[`For the high and lofty One who inhabits eternity, whose name is Holy, says: “I dwell in the high and holy place, with him also who is of a contrite and humble spirit, to revive the spirit of the humble, and to revive the heart of the contrite.`]},"pr-lam-3-31-32":{e:`web`,t:[`For the Lord will not cast off forever.`,`For though he causes grief, yet he will have compassion according to the multitude of his loving kindnesses.`]},"pr-rom-4-18":{e:`web`,t:[`Besides hope, Abraham in hope believed, to the end that he might become a father of many nations, according to that which had been spoken, “So will your offspring be.”`]},"pr-ps-37-4":{e:`web`,t:[`Also delight yourself in Yahweh, and he will give you the desires of your heart.`]},"pr-jer-17-7":{e:`web`,t:[`“Blessed is the man who trusts in Yahweh, and whose confidence is in Yahweh.`]},"pr-mark-11-24":{e:`web`,t:[`Therefore I tell you, all things whatever you pray and ask for, believe that you have received them, and you shall have them.`]},"pr-isa-60-1":{e:`web`,t:[`“Arise, shine; for your light has come, and Yahweh’s glory has risen on you.`]},"pr-ps-16-11":{e:`web`,t:[`You will show me the path of life. In your presence is fullness of joy. In your right hand there are pleasures forever more.`]}};export{e as default};